<?php
require_once __DIR__.'/../config/app.php';
require_role('member');
$pageTitle='My dashboard';
$userId=(int)current_user()['id'];

// Dashboard metrics are based on the member's own records only.
$q=$pdo->prepare("SELECT s.*,p.name plan_name FROM subscriptions s JOIN membership_plans p ON p.id=s.plan_id WHERE s.user_id=? ORDER BY s.id DESC LIMIT 1");
$q->execute([$userId]); $subscription=$q->fetch();
$q=$pdo->prepare("SELECT COUNT(*) FROM attendance WHERE user_id=? AND MONTH(check_in)=MONTH(CURDATE()) AND YEAR(check_in)=YEAR(CURDATE())");
$q->execute([$userId]); $monthVisits=(int)$q->fetchColumn();
$q=$pdo->prepare("SELECT COUNT(*) FROM attendance WHERE user_id=?"); $q->execute([$userId]); $allVisits=(int)$q->fetchColumn();
$q=$pdo->prepare("SELECT COUNT(*) FROM workout_plans WHERE member_id=?"); $q->execute([$userId]); $workoutCount=(int)$q->fetchColumn();
$q=$pdo->prepare("SELECT COUNT(*) FROM bookings WHERE member_id=? AND status IN ('requested','confirmed') AND session_date>=NOW()"); $q->execute([$userId]); $upcomingCount=(int)$q->fetchColumn();
$q=$pdo->prepare("SELECT * FROM progress_records WHERE member_id=? ORDER BY recorded_at DESC LIMIT 2"); $q->execute([$userId]); $progressRows=$q->fetchAll();
$latestWeight=$progressRows[0]['weight_kg']??null;
$q=$pdo->prepare("SELECT * FROM bookings WHERE member_id=? AND session_date>=NOW() AND status IN ('requested','confirmed') ORDER BY session_date ASC LIMIT 3"); $q->execute([$userId]); $upcoming=$q->fetchAll();
$q=$pdo->prepare("SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 4"); $q->execute([$userId]); $notifications=$q->fetchAll();
$q=$pdo->prepare("SELECT * FROM member_activities WHERE member_id=? ORDER BY activity_date DESC,id DESC LIMIT 5"); $q->execute([$userId]); $activities=$q->fetchAll();
$q=$pdo->prepare("SELECT * FROM fitness_goals WHERE member_id=? AND status='active' ORDER BY target_date IS NULL,target_date ASC LIMIT 3"); $q->execute([$userId]); $goals=$q->fetchAll();
$q=$pdo->prepare("SELECT COALESCE(SUM(duration_minutes),0) FROM member_activities WHERE member_id=? AND activity_date>=DATE_SUB(CURDATE(),INTERVAL 6 DAY)"); $q->execute([$userId]); $weekMinutes=(int)$q->fetchColumn();
$q=$pdo->prepare("SELECT activity_date,COALESCE(SUM(duration_minutes),0) minutes FROM member_activities WHERE member_id=? AND activity_date>=DATE_SUB(CURDATE(),INTERVAL 6 DAY) GROUP BY activity_date"); $q->execute([$userId]); $dailyRows=$q->fetchAll(PDO::FETCH_KEY_PAIR);
$weeklyBars=[]; for($i=6;$i>=0;$i--){$day=date('Y-m-d',strtotime('-'.$i.' days'));$weeklyBars[]=['label'=>date('D',strtotime($day)),'minutes'=>(int)($dailyRows[$day]??0)];} $maxDaily=max(30,...array_column($weeklyBars,'minutes'));
$activeDays=count(array_filter($weeklyBars,fn($d)=>$d['minutes']>0));
include __DIR__.'/../includes/header.php';
?>
<div class="dashboard-layout"><?php include __DIR__.'/../includes/sidebar.php'; ?>
<main class="dashboard-main member-dashboard">
 <div class="dash-top"><div><span class="eyebrow">IRONX MEMBER SPACE</span><h1>Your fitness command centre</h1><p class="dash-subtitle">A clear view of your training, consistency and next steps.</p></div><div class="dash-top-actions"><span class="user-pill"><?= e(current_user()['name']) ?></span><a class="btn btn-dark btn-small" href="<?= BASE_URL ?>/member/activities.php">＋ Log activity</a></div></div>
 <section class="member-welcome"><div class="welcome-copy"><span class="welcome-kicker">WELCOME BACK TO IRONX</span><h2>Show up. Put in the work.<br><em>Build your strength.</em></h2><p>Good progress comes from consistent effort. Use your dashboard to plan sessions, track activity and stay accountable.</p><div class="welcome-actions"><a class="btn btn-white" href="<?= BASE_URL ?>/member/workouts.php">View my workouts <span>→</span></a><a class="welcome-text-link" href="<?= BASE_URL ?>/index.php">IRONX home ↗</a></div></div><div class="welcome-mark"><img src="<?= BASE_URL ?>/assets/images/ironx-mark.png" alt="IRONX shield"></div><div class="welcome-bottom"><span>YOUR JOURNEY, YOUR PACE</span><span><?= date('l, d M Y') ?></span></div></section>
 <section class="member-stats-grid">
  <article class="member-stat"><span class="stat-icon">◷</span><small>Visits this month</small><strong><?= $monthVisits ?></strong><span class="stat-foot">Total visits: <?= $allVisits ?></span></article>
  <article class="member-stat"><span class="stat-icon">▤</span><small>Workout plans</small><strong><?= $workoutCount ?></strong><span class="stat-foot">Assigned to your account</span></article>
  <article class="member-stat"><span class="stat-icon">↗</span><small>Upcoming sessions</small><strong><?= $upcomingCount ?></strong><span class="stat-foot">Requested or confirmed</span></article>
  <article class="member-stat"><span class="stat-icon">◎</span><small>Latest weight</small><strong><?= $latestWeight!==null ? e(number_format((float)$latestWeight,1)).'<small class="unit"> kg</small>' : '—' ?></strong><span class="stat-foot"><?= $latestWeight!==null?'From your latest progress entry':'Add your first progress entry' ?></span></article>
 </section>
 <section class="member-analytics-strip">
  <div class="analytics-intro"><span class="eyebrow">YOUR PERFORMANCE</span><h2>Consistency builds results.</h2><p>Your training activity over the last seven days.</p><div class="analytics-highlight"><strong><?= $activeDays ?><small>/7</small></strong><span>active days this week</span></div><a class="inline-arrow" href="<?= BASE_URL ?>/member/progress.php">Explore progress analytics →</a></div>
  <div class="weekly-chart" role="img" aria-label="Weekly activity chart showing minutes logged per day">
   <div class="chart-topline"><div><span>WEEKLY ACTIVITY</span><strong><?= $weekMinutes ?> <small>minutes</small></strong></div><span class="chart-period">LAST 7 DAYS</span></div>
   <div class="chart-bars"><?php foreach($weeklyBars as $bar): $height=$bar['minutes']>0?max(8,($bar['minutes']/$maxDaily)*100):4; ?><div class="chart-day"><div class="bar-track"><span class="bar-fill" style="height:<?= $height ?>%" title="<?= $bar['minutes'] ?> minutes"></span></div><small><?= e($bar['label']) ?></small></div><?php endforeach; ?></div>
   <div class="chart-legend"><span><i></i> Activity minutes</span><span>Log activities to build your trend</span></div>
  </div>
 </section>
 <div class="member-content-grid">
  <section class="member-card member-plan-card"><div class="card-heading"><div><span class="eyebrow">MEMBERSHIP</span><h2>Your plan</h2></div><a href="<?= BASE_URL ?>/member/membership.php">Details ↗</a></div><?php if($subscription): ?><div class="plan-line"><div><strong><?= e($subscription['plan_name']) ?></strong><span><?= e(date('d M Y',strtotime($subscription['start_date']))) ?> – <?= e(date('d M Y',strtotime($subscription['end_date']))) ?></span></div><span class="status-chip <?= e($subscription['status']) ?>"><?= e(ucfirst($subscription['status'])) ?></span></div><div class="plan-note">Keep your routine consistent and make every visit count.</div><?php else: ?><p class="empty-note">You don't have an active membership on record yet.</p><a class="btn btn-dark btn-small" href="<?= BASE_URL ?>/membership.php">Explore memberships</a><?php endif; ?></section>
  <section class="member-card consistency-card"><div class="card-heading"><div><span class="eyebrow">THIS WEEK</span><h2>Time invested</h2></div><span class="consistency-icon">✦</span></div><strong class="big-metric"><?= $weekMinutes ?><small> min</small></strong><p>Activity minutes logged over the last seven days.</p><a href="<?= BASE_URL ?>/member/activities.php" class="inline-arrow">View activity history →</a></section>
 </div>
 <div class="member-content-grid lower-grid">
  <section class="member-card"><div class="card-heading"><div><span class="eyebrow">STAY ON TRACK</span><h2>Your active goals</h2></div><a href="<?= BASE_URL ?>/member/goals.php">All goals ↗</a></div><?php if($goals): foreach($goals as $goal): $pct=$goal['target_value']>0?min(100,max(0,((float)$goal['current_value']/(float)$goal['target_value'])*100)):0; ?><div class="goal-preview"><div class="goal-preview-top"><strong><?= e($goal['title']) ?></strong><span><?= e(rtrim(rtrim(number_format((float)$goal['current_value'],1),'0'),'.')) ?> / <?= e(rtrim(rtrim(number_format((float)$goal['target_value'],1),'0'),'.')) ?> <?= e($goal['unit']) ?></span></div><div class="progress-track"><span style="width:<?= $pct ?>%"></span></div><small><?= round($pct) ?>% complete<?= $goal['target_date']?' · Target '.e(date('d M',strtotime($goal['target_date']))):'' ?></small></div><?php endforeach; else: ?><p class="empty-note">Set a personal target and make your progress measurable.</p><a class="btn btn-outline-purple btn-small" href="<?= BASE_URL ?>/member/goals.php">Create a fitness goal</a><?php endif; ?></section>
  <section class="member-card"><div class="card-heading"><div><span class="eyebrow">UP NEXT</span><h2>Upcoming sessions</h2></div><a href="<?= BASE_URL ?>/member/bookings.php">Manage ↗</a></div><?php if($upcoming): foreach($upcoming as $booking): ?><div class="upcoming-row"><div class="date-tile"><strong><?= e(date('d',strtotime($booking['session_date']))) ?></strong><small><?= e(date('M',strtotime($booking['session_date']))) ?></small></div><div class="upcoming-info"><strong>Training session</strong><span><?= e(date('l · h:i A',strtotime($booking['session_date']))) ?></span></div><span class="status-chip <?= e($booking['status']) ?>"><?= e(ucfirst($booking['status'])) ?></span></div><?php endforeach; else: ?><p class="empty-note">No upcoming sessions yet. Request a trainer session when you're ready.</p><a class="inline-arrow" href="<?= BASE_URL ?>/member/bookings.php">Book a session →</a><?php endif; ?></section>
 </div>
 <div class="member-content-grid lower-grid">
  <section class="member-card"><div class="card-heading"><div><span class="eyebrow">RECENT MOVEMENT</span><h2>Activity log</h2></div><a href="<?= BASE_URL ?>/member/activities.php">See all ↗</a></div><?php if($activities): foreach($activities as $activity): ?><div class="activity-row"><span class="activity-dot"></span><div><strong><?= e($activity['activity_type']) ?></strong><span><?= e(date('d M Y',strtotime($activity['activity_date']))) ?> · <?= (int)$activity['duration_minutes'] ?> min<?= $activity['calories_burned']?' · '.(int)$activity['calories_burned'].' kcal':'' ?></span></div></div><?php endforeach; else: ?><p class="empty-note">Your completed sessions and activities will appear here when you log them.</p><?php endif; ?><a class="inline-arrow" href="<?= BASE_URL ?>/member/activities.php">＋ Add an activity →</a></section>
  <section class="member-card"><div class="card-heading"><div><span class="eyebrow">FROM IRONX</span><h2>Notifications</h2></div><span class="notification-count"><?= count(array_filter($notifications,fn($n)=>(int)$n['is_read']===0)) ?> new</span></div><?php if($notifications): foreach($notifications as $notice): ?><div class="notice-row"><span class="notice-dot <?= (int)$notice['is_read']===0?'unread':'' ?>"></span><div><p><?= e($notice['message']) ?></p><small><?= e(date('d M · h:i A',strtotime($notice['created_at']))) ?></small></div></div><?php endforeach; else: ?><p class="empty-note">You're all caught up. Important account and training updates will appear here.</p><?php endif; ?></section>
